<?php namespace Workspace; ?>
<section class="panel inset"><h2>Сайты CajeerEngine</h2><form method="get" class="inline"><input type="hidden" name="p" value="engine"><label>Проект<select name="project" required><?php selectOptions($projects,$project) ?></select></label><button>Открыть</button></form>
<?php if($project!==null): foreach($sites as $s): ?><div class="splitrow"><div><a href="<?= h(url('engine',['project'=>$project,'site'=>$s['id']])) ?>"><?= h($s['name']) ?></a><small><?= h($s['connection_key']) ?> · <?= $s['active']?'активен':'отключён' ?></small></div><?php if($user['role']==='owner'): ?><form method="post"><?php formFields('engine.toggle') ?><input type="hidden" name="project_id" value="<?= h($project) ?>"><input type="hidden" name="site_id" value="<?= h($s['id']) ?>"><input type="hidden" name="active" value="<?= $s['active']?'0':'1' ?>"><button class="secondary"><?= $s['active']?'Отключить':'Включить' ?></button></form><?php endif ?></div><?php endforeach ?>
<?php if($user['role']==='owner'&&$available): ?><form method="post" class="formgrid"><?php formFields('engine.bind') ?><input type="hidden" name="project_id" value="<?= h($project) ?>"><label>Подключение<select name="connection" required><?php selectOptions($available) ?></select></label><label>Название сайта<input name="name" maxlength="120" required></label><button>Привязать сайт</button></form><?php endif ?><?php endif ?></section>
<?php if($error): ?><p class="notice"><?= h($error) ?></p><?php endif ?>
<?php if($site&&!$publication&&!$error): ?><section class="panel inset"><h2><?= h($site['name']) ?> · Каталог материалов</h2><form method="get" class="inline"><input type="hidden" name="p" value="engine"><input type="hidden" name="project" value="<?= h($project) ?>"><input type="hidden" name="site" value="<?= h($site['id']) ?>"><label>Тип<select name="type" required><?php selectOptions($types,$type) ?></select></label><label>Поиск<input name="q" value="<?= h($q) ?>" maxlength="128"></label><button>Читать</button></form>
<?php foreach($items as $eid=>$row): ?><div class="splitrow"><div><a href="<?= h(url('engine',['project'=>$project,'site'=>$site['id'],'type'=>$type,'entry'=>$eid,'revision'=>$row['revision'],'q'=>$q,'offset'=>$offset+1])) ?>"><?= h($row['title']) ?></a><small><?= h($row['status'].' · '.$row['locale'].' · v'.$row['revision']) ?></small></div></div><?php endforeach ?>
<?php if($type!==''): ?><p>Записей: <?= h($total) ?>. <?php if($offset>0): ?><a href="<?= h(url('engine',['project'=>$project,'site'=>$site['id'],'type'=>$type,'q'=>$q,'offset'=>max(1,$offset-19)])) ?>">Назад</a><?php endif ?> <?php if($offset+20<$total&&$offset+20<=1000000): ?><a href="<?= h(url('engine',['project'=>$project,'site'=>$site['id'],'type'=>$type,'q'=>$q,'offset'=>$offset+21])) ?>">Далее</a><?php endif ?></p><?php endif ?></section>
<?php if($preview): $snap=$preview['snapshot']; ?><section class="panel inset"><h2>Предпросмотр · <?= h($snap['title']) ?> · v<?= h($snap['revision']) ?></h2><p>Безопасный просмотр данных редакции, не рендеринг темы. SHA-256: <code><?= h($preview['hash']) ?></code></p><p><?php foreach($history as $n=>$rev): ?><a href="<?= h(url('engine',['project'=>$project,'site'=>$site['id'],'type'=>$type,'entry'=>$entry,'revision'=>$n,'q'=>$q,'offset'=>$offset+1])) ?>">v<?= h($n) ?></a> · <?php endforeach ?></p><pre class="engine-preview"><?= h(json_encode($snap,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)) ?></pre>
<?php if($canPublish&&$preview['publishable']): ?><form method="post"><?php formFields('engine.prepare') ?><input type="hidden" name="project_id" value="<?= h($project) ?>"><input type="hidden" name="site_id" value="<?= h($site['id']) ?>"><input type="hidden" name="type" value="<?= h($type) ?>"><input type="hidden" name="entry" value="<?= h($entry) ?>"><input type="hidden" name="revision" value="<?= h($snap['revision']) ?>"><input type="hidden" name="hash" value="<?= h($preview['hash']) ?>"><button>Подготовить к публикации</button></form><?php else: ?><p>Публиковать можно только текущий черновик при наличии прав менеджера.</p><?php endif ?></section><?php endif ?><?php endif ?>
<?php if($publication): $p=$publication; ?><section class="panel inset"><h2>Публикация #<?= h($p['id']) ?> · <?= h(ENGINE_STATES[$p['state']]) ?></h2><p><?= h($site['name'].' · '.$p['content_type'].' · '.$p['entry_id'].' · v'.$p['revision']) ?></p><p><?= h($p['detail']) ?></p><p>SHA-256: <code><?= h($p['snapshot_hash']) ?></code></p><pre class="engine-preview"><?= h(json_encode(json_decode($p['snapshot'],true,64,JSON_THROW_ON_ERROR),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)) ?></pre>
<?php if($p['public_url']): ?><p>Маршрут на момент последней сверки: <a href="<?= h($p['public_url']) ?>" target="_blank" rel="noopener noreferrer"><?= h($p['public_url']) ?></a></p><?php endif ?>
<?php if($canPublish): foreach($p['state']==='ready'?['engine.confirm'=>'Подтвердить публикацию','engine.cancel'=>'Отменить']: (in_array($p['state'],['sending','uncertain','published','observed'],true)?['engine.reconcile'=>'Сверить с Engine']:[]) as $action=>$label): ?><form method="post" class="inline"><?php formFields($action) ?><input type="hidden" name="project_id" value="<?= h($project) ?>"><input type="hidden" name="publication" value="<?= h($p['id']) ?>"><input type="hidden" name="hash" value="<?= h($p['snapshot_hash']) ?>"><?php if($action==='engine.confirm'): ?><label><input type="checkbox" name="confirm" value="yes" required> Проверил снимок, разрешаю публичную публикацию</label><?php endif ?><button><?= h($label) ?></button></form><?php endforeach ?><?php endif ?></section><?php endif ?>
<?php if($project!==null): ?><section class="panel inset"><h2>Последние публикации (до 50)</h2><?php foreach($publications as $p): ?><div class="splitrow"><a href="<?= h(url('engine',['project'=>$project,'publication'=>$p['id']])) ?>">#<?= h($p['id'].' · '.$p['content_type'].' · v'.$p['revision']) ?></a><span><?= h(ENGINE_STATES[$p['state']]) ?></span></div><?php endforeach ?></section><?php endif ?>
